#[capability(
    module = "bigcommerce",
    id = "product-variants-get-product-variants",
    display_name = r##"List Product Variants"##,
    description = r##"Returns a list of product variants. Optional parameters can be passed in."##
)]
pub async fn product_variants_get_product_variants(
    input: ProductVariantsGetProductVariantsInput,
) -> Result<ProductVariantsGetProductVariantsResponse200, AgentError> {
    let connection = kit::require_connection(&input._connection, "BIGCOMMERCE")?;
    input.request()?.send(connection, "BIGCOMMERCE").await
}

impl ProductVariantsGetProductVariantsInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = format!(
            "/v3/catalog/products/{product_id}/variants",
            product_id = kit::encode_path(&self.product_id)
        );
        let request = kit::Request::new("GET", path)
            .query_opt("include_fields", &self.include_fields)
            .query_opt("exclude_fields", &self.exclude_fields)
            .query_opt("page", &self.page)
            .query_opt("limit", &self.limit);
        Ok(request)
    }
}

