#[capability(
    module = "bigcommerce",
    id = "transactions-get-order-transactions",
    display_name = r##"List Transactions"##,
    description = r##"Returns an **orderʼs** transactions.

**Usage Notes**
* Depending on the payment method, different information will be available (not all payment gateways return full card or fraud detail).


Requires at least one of the following scopes:
* `store_v2_transactions_read_only`
* `store_v2_transactions`"##
)]
pub async fn transactions_get_order_transactions(
    input: TransactionsGetOrderTransactionsInput,
) -> Result<TransactionsGetOrderTransactionsResponse200, AgentError> {
    let connection = kit::require_connection(&input._connection, "BIGCOMMERCE")?;
    input.request()?.send(connection, "BIGCOMMERCE").await
}

impl TransactionsGetOrderTransactionsInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = format!(
            "/v3/orders/{order_id}/transactions",
            order_id = kit::encode_path(&self.order_id)
        );
        let request = kit::Request::new("GET", path);
        Ok(request)
    }
}

